  "measure_id": "MEAS-93C31E24",
  "restatements": [
    {
      "clause_id": "§1",
      "text": "Requires voters to show a current government-issued photo ID at the polling place before receiving a ballot."
    },
    {
      "clause_id": "§2",
      "text": "Allows voters without ID to cast a provisional ballot, which will be counted only if they present identification to the county clerk within six days after the election."
    }
  ],
